#include <stdio.h>
#include <string.h>

int main(int argc, char **argv) {
    const int MAX_ARGS = 64;      // maximum number of arguments allowed (excluding program name)
    const int MAX_LEN  = 1024;    // maximum length of any argument (allowed up to 1024 characters)

    int user_args = argc - 1; // number of arguments provided by the user

    if (user_args > MAX_ARGS) {
        puts("TOO_MANY");
        return 0;
    }
    if (user_args == 0) {
        puts("EMPTY");
        return 0;
    }

    // Verify each argument length does not exceed the limit
    for (int i = 1; i < argc; ++i) {
        if ((int)strlen(argv[i]) > MAX_LEN) {
            puts("TOO_LONG");
            return 0;
        }
    }

    // Compute the longest common prefix among all arguments
    const char *first = argv[1];
    size_t prefix_len = strlen(first);
    for (int i = 2; i < argc; ++i) {
        size_t j = 0;
        while (j < prefix_len && first[j] && argv[i][j] && first[j] == argv[i][j]) {
            ++j;
        }
        prefix_len = j;
        if (prefix_len == 0) {
            break; // no common prefix left
        }
    }

    // Output the common prefix followed by a newline
    fwrite(first, 1, prefix_len, stdout);
    putchar('\n');
    return 0;
}
